"""Trauma Team: stabilization, death and Death State, healing over time, speedheal and nanotech, Trauma Team,
drugs and the drug lab, the bodyshop, surgery, and the GM's medical tools."""
import asyncio, os
from playwright.async_api import async_playwright
from harness import *

SHOTS=os.path.join(OUT,"med");os.makedirs(SHOTS,exist_ok=True)
def shot(n):return os.path.join(SHOTS,n)
# rig the dice: each [sides, value] is the next d(sides); after that, rolls come up in the middle.
# Only d() draws from the queue, so ids and anything else random can't eat a rigged roll.
RIG="window.__mr=window.__mr||Math.random;window.rig=l=>{const q=l.map(([n,v])=>(v-0.5)/n);Math.random=()=>{if(!/at d \\(/.test(new Error().stack))return window.__mr();return q.length?q.shift():0.45}};0"
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pl=await page(b,"P","player.html");pl.set_default_timeout(8000)
        await make_runner(pl,"Razor")
        await pl.click(".card:has-text('Razor') >> text=Open sheet");await pl.wait_for_timeout(300)
        await pl.evaluate(RIG)
        J=lambda s:pl.evaluate(s)
        # calc: effects and permanent losses
        ref0=await J("calc(curChar()).eff.REF");st0=await J("calc(curChar()).stunSave")
        await J("(()=>{const c=curChar();c.fx=[{id:'t',name:'Test',mods:{REF:2},stun:2}];c.statLoss={REF:1};saveChar(c,true)})()")
        ok(await J("calc(curChar()).eff.REF")==ref0+1 and await J("calc(curChar()).stunSave")==st0+2,"running effects and permanent losses change the stats; pain drugs add to Stun saves")
        await J("(()=>{const c=curChar();c.fx=[];c.statLoss={};c.eb=60000;c.wounds=22;c.skills['First Aid']={c:4,p:0,b:0};c.skills['Pharmaceuticals']={c:0,p:6,b:0};saveChar(c,true);render()})()")
        await pl.click("[data-act=tab][data-t=med]");await pl.wait_for_timeout(150)
        t=await pl.text_content("main");ok("Not stabilized" in t and "death save every turn" in t,"a mortal wound: not stabilized, death saves every turn")
        ok(await pl.locator("[data-act=roll-save][data-t=death]").count()==1,"the death save button is on the sheet")
        # stabilize
        await pl.click("[data-act=med-who][data-v=self]");await pl.wait_for_timeout(100)
        ok(await pl.locator("[data-act=med-stab][disabled]").count()==1,"you can't stabilize yourself")
        await pl.click("[data-act=med-who][data-v=other]");await pl.fill("input[data-medui=tot]","14");await pl.click("[data-act=med-adv][data-v=hospital]");await pl.wait_for_timeout(100)
        await J("rig([[10,2]])");await pl.click("[data-act=med-stab]");await pl.wait_for_timeout(100)
        ok(not await J("medStable(curChar())") and "Failed" in str(await J("Dice.log[0].tags")),"14 + hospital 5 + 2 = 21: short of 22 damage")
        await J("rig([[10,3]])");await pl.click("[data-act=med-stab]");await pl.wait_for_timeout(100)
        ok(await J("medStable(curChar())") and await J("curChar().med.stabW")==22,"14 + 5 + 3 = 22: stabilized at 22")
        ok(await pl.locator("[data-act=roll-save][data-t=death]").count()==0 and "Stabilized" in await pl.text_content("main"),"no more death saves once stabilized")
        await J("(()=>{const c=curChar();c.wounds=23;saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        ok(not await J("medStable(curChar())"),"another wound and it starts again")
        await J("(()=>{const c=curChar();c.wounds=22;saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        # treatment
        await J("rig([[10,8]])");await pl.click("[data-act=med-treat][data-s=first]");await pl.wait_for_timeout(100)
        ok(not await J("curChar().med.treat"),"First Aid has to beat the damage: 22 vs 22 fails")
        await J("rig([[10,9]])");await pl.click("[data-act=med-treat][data-s=first]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.treat")=="first" and await J("healRate(curChar())")==0.5,"First Aid: half a point a day")
        await J("rig([[10,9]])");await pl.click("[data-act=med-treat][data-s=medtech]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.treat")=="medtech" and await J("healRate(curChar())")==1,"Medical Tech supersedes it: 1 point a day")
        eb=await J("curChar().eb");await J("rig([[6,6],[6,6]])");await pl.click("[data-act=med-speed]");await pl.wait_for_timeout(100)
        sp=await J("curChar().fx.find(f=>f.name==='Speedheal: −REF')")
        ok(await J("healRate(curChar())")==2 and await J("curChar().eb")==eb-1650 and sp and sp["mods"]["REF"]==-2 and sp["days"]==7,"speedheal: 2 a day, 1,650eb, and −1D6/3 REF for a week")
        await J("rig([[10,4]])");await pl.click("[data-act=med-nano]");await pl.wait_for_timeout(100)
        ok(not await J("curChar().med.nano") and await J("curChar().eb")==eb-1650,"nanotech: this hospital doesn't have it (only 1 in 10)")
        await J("rig([[10,1]])");await pl.click("[data-act=med-nano]");await pl.wait_for_timeout(100)
        ok(await J("healRate(curChar())")==3 and await J("curChar().eb")==eb-1650-1500,"nanotech + speedheal + Medical Tech: 3 a day")
        await J("(()=>{const c=curChar();c.cyber.push(mkCyber(CYBER.find(r=>r[0]==='Enhanced antibodies'),1));saveChar(c,true);render()})()")
        ok(await J("healRate(curChar())")==4,"enhanced antibodies add 1")
        await J("(()=>{const c=curChar();c.cyber.push(mkCyber(CYBER.find(r=>r[0]==='Nanosurgeons'),1));saveChar(c,true);render()})()")
        ok(await J("healRate(curChar())")==8 and await J("daysToHeal(curChar())")==3,"nanosurgeons double it: 8 a day, 3 days to heal 22")
        await J("(()=>{const c=curChar();c.cyber=c.cyber.filter(x=>!/Nanosurgeons|antibodies/.test(x.name));saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        await pl.screenshot(path=shot("med-tab.png"),full_page=True)
        refsp=await J("calc(curChar()).eff.REF")
        await pl.click("[data-act=med-days][data-n='7']");await pl.wait_for_timeout(150)
        ok(await J("curChar().wounds")==1 and "Healed 21 points in 7 days" in await J("curChar().med.log.join(' ')"),"a week at 3 a day: 21 points healed")
        ok(await J("calc(curChar()).eff.REF")>refsp and not await J("curChar().fx.length"),"the speedheal REF penalty wears off after the week")
        await pl.click("[data-act=med-days][data-n='1']");await pl.wait_for_timeout(100)
        ok(await J("curChar().wounds")==0 and not await J("curChar().med.treat") and not await J("curChar().med.speedheal"),"fully healed: treatment over")
        # untreated
        await J("(()=>{const c=curChar();c.wounds=14;c.med={};saveChar(c,true);render()})()");await J("rig([[10,9]])")
        await pl.click("[data-act=med-days][data-n='1']");await pl.wait_for_timeout(100)
        ok(await J("curChar().wounds")==16 and await J("curChar().med.dead"),"untreated: +2 a day, and a failed daily death save kills")
        # death and Death State
        await J("(()=>{const c=curChar();c.wounds=18;c.med={};saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        ds=await J("calc(curChar()).deathSave");await J(f"rig([[10,{ds+1}]])");await pl.click("[data-act=roll-save][data-t=death]");await pl.wait_for_timeout(150)
        ok(await J("curChar().med.dying") and "Dying this turn" in await pl.text_content("main"),"a failed death save: dying at the end of the turn")
        await pl.click("[data-act=med-die]");await pl.click("[data-act=med-min]");await pl.click("[data-act=med-min]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.ds")==4 and "Death State 4" in await pl.text_content("main"),"dead: Death State +2 a minute")
        await pl.screenshot(path=shot("med-dead.png"),full_page=True)
        await J("rig([[10,7]])");await pl.click("[data-act=med-revive]");await pl.wait_for_timeout(100)
        ok(not await J("curChar().med.dead") and await J("medStable(curChar())"),"1D10 7 over Death State 4: revived and stabilized")
        await J("(()=>{const c=curChar();c.med={dead:true,ds:4};saveChar(c,true);render()})()");await J("rig([[10,4]])");await pl.click("[data-act=med-revive]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.gone") and "Dead for good" in await pl.text_content("main"),"a 4 doesn't beat 4: gone")
        await J("(()=>{const c=curChar();c.med={dead:true,ds:8};saveChar(c,true);render()})()");await pl.click("[data-act=med-min]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.gone"),"Death State 10: dead for good")
        # Trauma Team
        await J("(()=>{const c=curChar();c.med={};c.wounds=20;saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        eb=await J("curChar().eb");await J("rig([[6,3]])");await pl.click("[data-act=med-ttcall]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.ttEta")==4 and "arrives in 4 minutes" in await pl.text_content("main"),"Trauma Team arrives in 1D6+1 minutes")
        await pl.click("[data-act=med-ttarrive]");await pl.wait_for_timeout(100)
        ok("tt" in await J("medUI(curChar().id).adv") and await J("curChar().med.ttBill")==8,"they're here: +3 to stabilize, and 8 minutes on the bill")
        await pl.click("[data-act=med-ttbill]");await pl.wait_for_timeout(100)
        ok(await J("curChar().eb")==eb-800,"no account: 100eb a minute")
        await pl.select_option("select[data-act-change=med-ttcov]","account");await pl.wait_for_timeout(100)
        await J("rig([[6,1]])");await pl.click("[data-act=med-ttcall]");await pl.click("[data-act=med-ttarrive]");await pl.wait_for_timeout(100)
        ok(await J("curChar().med.ttBill")==0,"with an account the run is covered")
        # drugs
        await J("(()=>{const c=curChar();c.med={};c.wounds=0;saveChar(c,true);render()})()")
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Drugs]");await pl.wait_for_timeout(200)
        names=await J("medShopList(curChar()).map(x=>x.name)")
        ok(all(n in names for n in ["SynthCoke","Stim","Syncomp 15","Speedheal","Boost","Blue Glass","Smash","'Dorph","Black Lace"]),"the book's street drugs are in the shop")
        await pl.locator(".shop-row:has-text('Black Lace')").hover();await pl.wait_for_timeout(300)
        t=(await pl.inner_text("#shop-detail")).lower();ok("+2 cool" in t and "difficulty 13" in t,"a drug's card: its effects and Difficulty")
        for n in ["'Dorph","Black Lace","Smash"]:
            i=names.index(n);await pl.click(f"[data-act=buy][data-k=dr][data-i='{i}']");await pl.wait_for_timeout(60)
        ok(await J("curChar().gear.find(g=>g.name==='Smash').qty")==6,"Smash comes in a 6-pack")
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        st0=await J("calc(curChar()).stunSave");ref0=await J("curChar().stats.REF-(curChar().statLoss?.REF||0)")
        gid=await J("curChar().gear.find(g=>g.name===\"'Dorph\").id");await J("rig([[6,3],[10,1]])");await pl.click(f"[data-act=med-dose][data-gid='{gid}']");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).stunSave")==st0+2 and await J("curChar().statLoss.REF")==1,"'Dorph: +2 Stun saves, and a 1 on the extra 1D10 costs a point of REF for good")
        ok("Lasts 4 turns" in await J("Dice.log[0].detail"),"the dose lasts 1D6+1 turns")
        emp0=await J("calc(curChar()).eff.EMP");cool0=await J("calc(curChar()).eff.COOL")
        gid=await J("curChar().gear.find(g=>g.name==='Black Lace').id");await J("rig([[6,3],[10,10],[6,2]])");await pl.click(f"[data-act=med-dose][data-gid='{gid}']");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).eff.COOL")==cool0+2 and await J("calc(curChar()).eff.EMP")==max(0,emp0-2),"Black Lace: +2 COOL; failing the addiction save costs 1D6 EMP")
        ok(await J("curChar().gear.some(g=>g.name==='Black Lace')")==False,"the last dose is used up")
        await pl.screenshot(path=shot("med-drugs.png"),full_page=True)
        n=await pl.locator("[data-act=med-fxoff]").count();await pl.locator("[data-act=med-fxoff]").first.click();await pl.wait_for_timeout(100)
        ok(await pl.locator("[data-act=med-fxoff]").count()==n-1,"an effect can be marked as worn off")
        # the drug lab
        await pl.click("[data-act=open-modal][data-m=druglab]");await pl.wait_for_timeout(200)
        await pl.fill("#lab-name","Chrome Rush");await pl.check("input[data-act-change=lab-tog][data-k=fx][data-v=ref]");await pl.click("[data-act=lab-str][data-v='2']")
        await pl.check("input[data-act-change=lab-tog][data-k=sides][data-v=psych]");await pl.click("[data-act=lab-dur][data-v=hours]");await pl.wait_for_timeout(150)
        t=await pl.inner_text(".lab-sum");ok("27" in t and "675eb" in t,"(Increase REF 15 + Strength 2 − psychological addiction 8) × hours 3 = Difficulty 27, 675eb a dose")
        ok(await J("drugDiff({fx:['ref','int'],str:3,sides:['nerve','death','rage'],dur:'turns'})")==2,"the Difficulty never goes below 2")
        await pl.screenshot(path=shot("med-lab.png"))
        await J("rig([[10,3]])");await pl.click("[data-act=lab-make]");await pl.wait_for_timeout(150)
        ok(not await J("(curChar().drugsMade||[]).length") and "doesn't come out right" in await pl.inner_text(".modal"),"a failed Pharmaceuticals check: no drug")
        await J("rig([[10,10],[10,9]])");await pl.click("[data-act=lab-make]");await pl.wait_for_timeout(150)
        ok(await J("curChar().drugsMade[0].name")=="Chrome Rush","made it: the formula is saved")
        await pl.click("[data-act=close-modal]");await pl.click("[data-act=open-modal][data-m=shop][data-tab=Drugs]");await pl.wait_for_timeout(200)
        ok("Your formulas" in await pl.text_content(".shop-list"),"your formulas are at the Drugs counter")
        i=await J("medShopList(curChar()).findIndex(x=>x.name==='Chrome Rush')");eb=await J("curChar().eb")
        await pl.click(f"[data-act=buy][data-k=dr][data-i='{i}']");await pl.wait_for_timeout(100)
        ok(await J("curChar().eb")==eb-675,"a dose at its street price")
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        ref1=await J("calc(curChar()).eff.REF");gid=await J("curChar().gear.find(g=>g.name==='Chrome Rush').id");await pl.click(f"[data-act=med-dose][data-gid='{gid}']");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).eff.REF")==ref1+2,"Chrome Rush: +2 REF")
        await J("rig([[10,10]])");await pl.locator("[data-act=med-crave][data-v=psych]").click();await pl.wait_for_timeout(100)
        ok("has to find more" in await J("Dice.log[0].detail"),"addiction: the hourly COOL check")
        # bodyshop
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Drugs]");await pl.click("[data-act=shop-tab][data-t=Bodyshop]");await pl.wait_for_timeout(200)
        BS=await J("Object.fromEntries(BODYSHOP.map((x,i)=>[x[0],i]))");attr0=await J("calc(curChar()).eff.ATTR")
        await pl.click(f"[data-act=buy][data-k=bs][data-i='{BS['Bodysculpt: +1 ATTR']}']");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).eff.ATTR")==attr0+1,"bodysculpting: +1 ATTR for 600eb")
        g0=await J("curChar().gear.length");await J("rig([[10,2]])");await pl.click(f"[data-act=buy][data-k=bs][data-i='{BS['Body bank: arm']}']");await pl.wait_for_timeout(100)
        ok(await J("curChar().gear.length")==g0,"body bank: 1D10 2, not in today")
        await J("rig([[10,5]])");await pl.click(f"[data-act=buy][data-k=bs][data-i='{BS['Body bank: arm']}']");await pl.wait_for_timeout(100)
        ok("mismatch" in await J("curChar().gear[curChar().gear.length-1].notes"),"a 4 or 5: in, but a small mismatch")
        ok(await J(f"BODYSHOP[{BS['Vat-grown: arm']}][1]")==2000,"vat-grown: twice the body bank price")
        ref2=await J("calc(curChar()).eff.REF");await pl.click(f"[data-act=buy][data-k=bs][data-i='{BS['Exotic: hooves, claws or paws']}']");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).eff.REF")==max(0,ref2-2),"hooves or claws: −2 REF")
        # surgery
        await pl.click("[data-act=shop-tab][data-t=Cyberware]");await pl.wait_for_timeout(100)
        await pl.locator(".shop-row:has-text('Cyberarm')").hover();await pl.wait_for_timeout(300)
        ok("cr · critical" in (await pl.inner_text("#shop-detail")).lower(),"cyberware cards show the surgery code")
        await pl.check("input[data-act-change=shop-surg]");eb=await J("curChar().eb");w0=await J("curChar().wounds")
        ci=await J("CYBER.findIndex(r=>r[0]==='Cyberarm')");await J("rig([[6,1],[6,1],[6,2],[6,3],[6,4]])");await pl.click(f"[data-act=buy][data-k=c][data-i='{ci}']");await pl.wait_for_timeout(150)
        ok(await J("curChar().wounds")==w0+10 and await J("curChar().eb")==eb-3000-2500 and await J("curChar().med.treat")=="medtech","Critical surgery: 3D6+1 = 10 damage and 2,500eb, healing at the Medical Tech rate")
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        # treat someone else
        await pl.fill("input[data-medui=pdmg]","15");await J("rig([[10,9]])");await pl.click("[data-act=med-medic][data-s=first]");await pl.wait_for_timeout(100)
        k=await J("[calc(curChar()).eff.TECH,skillLevel(curChar(),'First Aid')]")
        ok(("worked" if k[0]+k[1]+9>15 else "failed") in await pl.text_content("main"),"treating someone else uses your TECH + First Aid")
        print("player errors:",errs)

        # ---------------- GM ----------------
        gm=await page(b,"GM","gm.html");gm.set_default_timeout(8000);await gm.evaluate(RIG)
        await gm.evaluate("()=>{const c=normalizeChar({...clone(SAMPLE),id:'pc1',handle:'Ghost',wounds:21,med:{}});st.party.push(c);persist();render()}")
        await gm.click("nav [data-act=tab][data-t=party]");await gm.wait_for_timeout(150)
        ok("Not stabilized" in await gm.text_content("main"),"the party list shows who needs stabilizing")
        await gm.click("[data-act=open-pc][data-id=pc1] >> nth=0");await gm.wait_for_timeout(200)
        t=await gm.text_content("main");ok("Condition" in t and "Treatment" in t and "Healing" in t,"the runner's page has their medical panels")
        await gm.fill("input[data-medui=tot][data-id=pc1]","15");await gm.evaluate("rig([[10,6]])");await gm.click("[data-act=med-stab][data-id=pc1]");await gm.wait_for_timeout(100)
        ok(await gm.evaluate("medStable(pc('pc1'))"),"the GM stabilizes a runner")
        await gm.evaluate("rig([[10,8]])");await gm.click("[data-act=med-treat][data-s=medtech][data-id=pc1]");await gm.wait_for_timeout(100)
        ok(await gm.evaluate("pc('pc1').med.treat")=="medtech","and treats them")
        await gm.screenshot(path=shot("gm-pc.png"),full_page=True)
        await gm.click("[data-act=close-pc]");await gm.wait_for_timeout(100)
        await gm.click("[data-act=open-modal][data-m=downtime]");await gm.fill("#dt-days","10");await gm.click("[data-act=med-downtime]");await gm.wait_for_timeout(150)
        ok(await gm.evaluate("pc('pc1').wounds")==11 and "Ghost" in await gm.inner_text(".modal"),"downtime: 10 days of Medical Tech heals 10")
        await gm.click("[data-act=close-modal]")
        # combat tracker
        await gm.evaluate("()=>{const c=pc('pc1');c.wounds=17;c.med={};persist()}")
        await gm.click("nav [data-act=tab][data-t=encounter]");await gm.wait_for_timeout(150)
        await gm.select_option("#enc-npc","t-corpsec");await gm.fill("#enc-count","1");await gm.click("[data-act=enc-add-npc]");await gm.wait_for_timeout(150)
        cid=await gm.evaluate("st.encounter.list[0].cid");await gm.evaluate(f"()=>{{st.encounter.list.find(x=>x.cid==='{cid}').npc.wounds=18;render()}}");await gm.wait_for_timeout(100)
        ok(await gm.locator(f"[data-act=cb-stab][data-cid='{cid}'][disabled]").count()==1,"stabilizing needs the medic's total")
        await gm.fill("#enc-medic","12");await gm.wait_for_timeout(600)
        await gm.evaluate("rig([[10,6]])");await gm.click(f"[data-act=cb-stab][data-cid='{cid}']");await gm.wait_for_timeout(150)
        ok(await gm.evaluate(f"medStable(st.encounter.list.find(x=>x.cid==='{cid}').npc)") and await gm.locator(f"#cb-{cid} [data-t=death]").count()==0,"12 + 6 = 18: the NPC is stabilized and stops making death saves")
        await gm.screenshot(path=shot("gm-encounter.png"),full_page=True)
        await gm.click("nav [data-act=tab][data-t=reference]");await gm.wait_for_timeout(150)
        t=await gm.text_content("main");ok(all(x in t for x in ["Stabilization","Death State","Healing rates","Surgery codes","Body bank","Bodysculpting","Street drugs","Drug designer: effects","Drug designer: side effects"]),"the rules reference has the medical tables")
        print("errors:",errs);ok(not errs,"no page errors")
        await b.close()
    finish()
asyncio.run(main())
